def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def removeDuplicates(arr):
    seen = set()
    out = []
    for x in arr:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def isValid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
    return len(stack) == 0

def mergeSorted(a, b):
    i, j = 0, 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

def longestCommonPrefix(strs):
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix

def findMissing(nums):
    n = len(nums) + 1
    total = n * (n + 1) // 2
    return total - sum(nums)

def integerSqrt(n):
    if n < 2:
        return n
    lo, hi = 1, n
    ans = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid <= n:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def lengthOfLIS(nums):
    if not nums:
        return 0
    tails = []
    for x in nums:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

def canFinish(numCourses, prerequisites):
    graph = {i: [] for i in range(numCourses)}
    for a, b in prerequisites:
        graph[a].append(b)
    state = [0] * numCourses
    def dfs(node):
        if state[node] == 1:
            return False
        if state[node] == 2:
            return True
        state[node] = 1
        for nxt in graph[node]:
            if not dfs(nxt):
                return False
        state[node] = 2
        return True
    for i in range(numCourses):
        if not dfs(i):
            return False
    return True

def knapsack(weights, values, capacity):
    n = len(weights)
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        w, v = weights[i - 1], values[i - 1]
        for c in range(capacity + 1):
            dp[i][c] = dp[i - 1][c]
            if w <= c:
                dp[i][c] = max(dp[i][c], dp[i - 1][c - w] + v)
    return dp[n][capacity]

def longestPalindrome(s):
    if not s:
        return ''
    start, best_len = 0, 1
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - l - 1
    for i in range(len(s)):
        l1, len1 = expand(i, i)
        l2, len2 = expand(i, i + 1)
        if len1 > best_len:
            start, best_len = l1, len1
        if len2 > best_len:
            start, best_len = l2, len2
    return s[start:start + best_len]

def hasCycle(start, next_nodes):
    slow = start
    fast = start
    while fast != -1 and next_nodes[fast] != -1:
        slow = next_nodes[slow]
        fast = next_nodes[next_nodes[fast]]
        if slow == fast:
            return True
    return False

from collections import OrderedDict
def lruCacheOps(capacity, operations):
    cache = OrderedDict()
    out = []
    for op in operations:
        if op[0] == 'put':
            key, value = op[1], op[2]
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
            out.append(None)
        else:
            key = op[1]
            if key in cache:
                cache.move_to_end(key)
                out.append(cache[key])
            else:
                out.append(-1)
    return out
